"""Native hash golden generated by the actual shared Node JCS/RuntimeDomainHash."""
from copy import deepcopy

import pytest

from beeos_cloud_harness_sdk.jcs import native_session_request_hash, verify_native_session_request


def rpc():
    return {"jsonrpc": "2.0", "id": "original-request", "method": "session/prompt", "params": {
        "10": "ten", "2": "two", "😀": {"counter": 9007199254740991, "negative": -9007199254740991},
        "\ue000": True, "parts": [{"type": "text", "text": "你好\u0000"}], "flags": [False, None, 0]}}


def test_matches_shared_node_and_state_golden():
    value = rpc()
    expected = "c4460acd7f0c8b202234ecad90149fc291844acba2ef153557ce279cc64ac8a0"
    assert native_session_request_hash(value) == expected
    carrier = {"method": "session/prompt", "request": value, "requestHash": expected}
    assert verify_native_session_request(carrier) == expected
    changed = deepcopy(carrier)
    changed["request"]["params"]["parts"][0]["text"] = "changed"
    with pytest.raises(ValueError, match="does not commit"):
        verify_native_session_request(changed)


@pytest.mark.parametrize("invalid", [1.0, 1e-6, float("nan"), float("inf"), 9007199254740992, -9007199254740992,
                                      (1, 2), {1: "non-string key"}, "\ud800", {"\udfff": "invalid key"}])
def test_rejects_values_outside_actual_state_native_json_domain(invalid):
    value = rpc()
    value["params"]["invalid"] = invalid
    with pytest.raises((ValueError, UnicodeError)):
        native_session_request_hash(value)


@pytest.mark.parametrize("invalid", [None, {}, {"jsonrpc": "2.0", "method": "session/clear"},
                                      {"jsonrpc": "1.0", "method": "session/prompt"}])
def test_requires_original_native_rpc(invalid):
    with pytest.raises(ValueError, match="Session RPC"):
        native_session_request_hash(invalid)


def test_rejects_wrong_carrier_method_and_missing_hash():
    for carrier in ({"method": "session/clear", "request": rpc()}, {"method": "session/prompt", "request": rpc()}):
        with pytest.raises(ValueError):
            verify_native_session_request(carrier)
